  str_n28_1_name_desc = "/",
  str_n28_2_name_desc = "Um caso sobre uma estátua decapitada é colocado sob sua responsabilidade, no entanto, a reclamação do autor não é dano à propriedade pública, mas... obstrução do amor?",
  str_n28_3_name_desc = "Nesta estação, quando o ardor do Mooncrown Day ainda paira no ar, Tina tem seus próprios desejos para perseguir.",
  str_n28_4_name_desc = "Vá e experimente o lendário Moonlight Salon, mergulhe na atmosfera amorosa e descubra a verdade!",
  str_n28_5_name_desc = "/",
  str_n28_6_name_desc = "É somente quando o constrangimento de Schwab se torna evidente que você percebe o terrível mal-entendido que ocorreu.",
  str_n28_7_name_desc = "Você encontra a organizadora do salão, uma freira comum de Lumopolis, mas recebe algumas respostas inesperadas.",
  str_n28_8_name_desc = "/",
  str_n28_9_name_desc = "Eclipsites, em um momento como este? Eles realmente são criaturas tão estranhas...",
  str_n28_10_name_desc = "À medida que a ameaça Eclipsite se aproxima gradualmente da estátua, não se esqueça de proteger a estátua na batalha!",
  str_n28_11_name_desc = "Livre-se dos perseguidores em seu encalço e prepare-se para lutar sem qualquer restrição!",
  str_n28_12_name_desc = "Os porões de todos os nobres estão cheios de tanta sujeira!?",
  str_n28_13_name_desc = "Não deixe que o menor detalhe passe sem escrutínio - revele a verdade por trás do caso no Tribunal de Justiça!",
  str_n28_14_name_desc = "A corte está sob o controle absoluto de Schwab! Não há mais nenhuma chance de que a justiça prevaleça aqui. Devemos encontrar uma maneira de sair disso primeiro, depois pensar em outra maneira!",
  str_n28_15_name_desc = "/",
  str_n28_1_name_desc_long = "Após o fim do festival Mooncrown Day, o charme persistente do amor ainda flutua pelas ruas de Lumopolis. Um casal apaixonado chega ao Tribunal de Justiça e faz uma cena. O caso até chama a atenção de Schwartz, que por acaso está presente para uma inspeção. Diante das próximas mudanças estruturais no Tribunal de Justiça, vários jovens juízes exibem reações diferentes—Leyn continua trabalhando alheio, Matthieu te convida e Carleen para compartilhar uma ocorrência interessante, e Tina, que é sempre tão alegre, parece ter suas próprias preocupações.",
  str_n28_2_name_desc_long = "O primeiro caso da Divisão Romance com o qual ninguém está disposto a lidar é colocado em suas mãos. Uma estátua foi decapitada e o autor insiste que a estátua sem vida é sua amante. Você vai até onde o Hall of Justice mantém exposições de casos e inspeciona a estátua em busca de pistas. Do lado de fora da janela, uma \"lua\" nasce silenciosamente.",
  str_n28_3_name_desc_long = "Sem pistas aparentes para seguir, Tina convida você para visitar sua casa. Acontece que ela está preocupada com algo há algum tempo e espera que você possa ajudá-la a concretizar seu plano de conhecê-lo. Você imediatamente entende pelas palavras de Tina que ela está secretamente apaixonada por seu novo chefe, Schwab.",
  str_n28_4_name_desc_long = "Você decide ir ao Moonlight Salon para tentar a sorte e ver se consegue encontrar o objeto de afeição de Tina. Tina também traz um presente que ela pretende dar. No salão, você dança, conversa e curte as canções festivas, mas a guarda da cidade de repente quebra esse momento feliz. Os guardas estão empenhados em suprimir esta reunião privada e, em meio ao caos, outra estátua é quebrada e o presente de Tina é perdido.",
  str_n28_5_name_desc_long = "Você imediatamente se dirige ao Hall of Justice para relatar o assunto, mas se depara com outro casal de amantes determinado a entrar em uma batalha legal acalorada. Os dois estavam de fato presentes no salão... Acontece que o presente perdido de Tina causou um desentendimento entre eles e, embora Tina corre para explicar a situação, o assunto toma um rumo inesperado...",
  str_n28_6_name_desc_long = "Por causa do depoimento de Tina no tribunal, Schwab acaba ficando constrangido na frente de todos. Depois de deixar o Hall of Justice, você percebe que foi rápido demais para adivinhar quem era a paixão de Tina, com base na explicação dela. O presente nunca foi feito para Schwab, mas na verdade para o pequeno Eclipsite que parece aparecer em todos os lugares - Toto.",
  str_n28_7_name_desc_long = "Antes de você se preparar para partir, Loewe repentinamente traz uma nova visão para Carleen na forma de novas informações. Parece que toda vez que o Moonlight Salon é realizado, tumultos acontecem e as cabeças das estátuas desaparecem misteriosamente. À luz dessa descoberta, o organizador do Moonlight Salon parece muito suspeito aos seus olhos, mas quando você o encontra novamente, suas suspeitas são dissipadas instantaneamente.",
  str_n28_8_name_desc_long = "Byron, o autor do caso da estátua decapitada, chega ao Tribunal de Justiça para registrar uma queixa e pede para ver os resultados da investigação o mais rápido possível. Recém-sem pistas, os juízes substituem a cabeça decepada da estátua em um ato de desespero. Claro, Byron não se diverte com tal gesto descuidado, mas ele não tem tempo para ficar com raiva - sua amada \"esposa estátua\" está em perigo. Os juízes imediatamente correm para a Stairway to the Skies, onde um desfile está prestes a acontecer.",
  str_n28_9_name_desc_long = "A estátua que requer proteção está no topo da escada, na direção da procissão que avança. Para evitar que a estátua seja destruída no caos, os juízes tentam impedir o desfile por meios não convencionais. Quando você está prestes a ter sucesso, os Eclipsites começam a se agitar na parte de trás do desfile e a multidão foge em direção à escada.",
  str_n28_10_name_desc_long = "Você tenta manter a estátua segura. Os eclipses se aproximam por trás da multidão e o pânico os cerca. No caos da batalha, uma mão sombria sai da escuridão e quebra a cabeça da estátua, mas pelo menos Leyn consegue tirar uma luva da mão do culpado desconhecido. O coração partido Byron retorna ao Tribunal de Justiça, enquanto Schwab parece ter certeza de que encerrou o caso, ordenando a prisão de Tina.",
  str_n28_11_name_desc_long = "A luva obtida por Leyn torna-se a principal evidência que aponta para a culpa de Tina, e Schwab a prende. Você acredita firmemente que Tina é inocente e não pode ignorar o comportamento estranho de Schwab, pois parece que ele a está incriminando. Talvez se você puder descobrir seus motivos, você pode exonerar Tina. Leyn decide arriscar e entra furtivamente na casa de Schwab para dar uma olhada.",
  str_n28_12_name_desc_long = "Você entra furtivamente na casa de Schwab para observá-lo. Embora o comportamento de Schwab seja um tanto estranho, não há nada de particularmente suspeito nele. Você abre a passagem para o porão de Schwab por acaso, e um enxame de Eclipsites emerge dela. Você foge da casa de Schwab em pânico - o tempo está se esgotando, pois o dia do julgamento se aproxima.",
  str_n28_13_name_desc_long = "O julgamento das \"Decapitações da Estátua Serial\" finalmente começa. Leyn e Matthieu Insista nisso Tina é inocente, e depois de uma defesa feroz, Leyn ataca a contradição entre a luva e a mão de Tina, limpando seu nome com sucesso. No entanto, este assunto está longe de terminar. Leyn convida uma testemunha especial para depor. Toto compareceu ao banco das testemunhas, pronto para provar que o verdadeiro culpado é Schwab.",
  str_n28_14_name_desc_long = "Totó e Leyn planejou com antecedência uma estratégia engenhosa, pela qual Toto fingiu ser o culpado pelo vandalismo das estátuas, trazendo com sucesso a trama de Schwab à tona. Em seu desespero, Schwab revela seu trunfo - ele substituiu os membros do júri por Eclipsites! Seu veredicto não tem nada a ver com a verdade. Você escapa do Hall of Justice, mas é confrontado pelo enlouquecido Schwab no portão. No final, você consegue subjugá-lo. O caso termina com o estouro do balão da lua - parece que a onda de romance que enche o ar vai desaparecer junto com ele.",
  str_n28_15_name_desc_long = "Irridon julga o caso novamente e condena o culpado. Essa farsa era bastante inofensiva, então Schwab não seria preso. Embora para ele, a punição que recebe pode ser ainda mais insuportável do que a prisão. Você e os juízes também recebem uma punição simbólica por seu comportamento pouco ortodoxo. Depois de receber o presente de Tina, Toto está pronto para embarcar em uma nova jornada; a partida dele deixa você ansioso pela próxima vez que se encontrarem. Enquanto os hinos flutuam no ar, Lumopolis volta a ser como era antes.",
  str_n28_h1_name = "H1 - Ataque",
  str_n28_h2_name = "H2 - Ruído Mortal",
  str_n28_h3_name = "H3 - Resolver",
  str_n28_h4_name = "H4 - A Perseguição",
  str_n28_h5_name = "H5 - Inflexível",
  str_n28_h6_name = "H6 - A Cavalaria",
  str_n28_h7_name = "EX1 - Esforce-se para sobreviver",
  str_n28_h8_name = "EX2 - Relâmpago Abrasador",
  str_n28_h9_name = "EX3 - Sombras Lâminadas",
  str_n28_h10_name = "EX4 - Enxame",
  str_n28_h11_name = "EX5 - Fúria do Sangue",
  str_n28_h12_name = "EX 6 - Golpe Central",
  str_n28_h1_name_desc = "Os inimigos são esquivos e se movem rapidamente, mas o mais assustador é que eles estão dispostos a sacrificar suas vidas para derrotá-lo.",
  str_n28_h2_name_desc = "Trovões estrondosos enchem o ar. Quando eles caírem, talvez você possa usar suas explosões poderosas para atacar os inimigos.",
  str_n28_h3_name_desc = "Embora o inimigo seja esmagador, com a ajuda de seus aliados, você pode virar a maré.",
  str_n28_h4_name_desc = "O terreno é complicado e seus inimigos são muitos - simplesmente sair vivo seria um milagre. Cuidado com os inimigos perseguindo você!",
  str_n28_h5_name_desc = "Cercado por inúmeros inimigos, como você pode abrir um caminho sangrento para a salvação? Além do mais, uma vez que esses inimigos morrem, eles se tornam cada vez mais fortes...",
  str_n28_h6_name_desc = "Eles se parecem com Lumo Knights, mas sob suas máscaras de pedra estão Eclipsites cruéis. Você não pode se dar ao luxo de cair!",
  str_n28_h7_name_desc = "Seus perseguidores estão se aproximando... Como seus aliados conseguirão sobreviver?",
  str_n28_h8_name_desc = "Chamas e explosões ecoantes o cercam... O inimigo parece imbatível, mas o tempo se tornará a chave para sua vitória.",
  str_n28_h9_name_desc = "Sombras espreitam em todos os cantos e lâminas afiadas procuram sua carne a cada passo. Uma dura batalha está à sua frente.",
  str_n28_h10_name_desc = "A inundação interminável de inimigos forma um enxame fervente, inundando o ninho na área central...",
  str_n28_h11_name_desc = "As lâminas do inimigo são tão afiadas quanto o vento cortante, e seus ataques são mais mortais do que um vendaval violento. Mais assustador do que isso é o fato de que, uma vez intoxicados pelo cheiro de sangue, eles se tornam ainda mais fortes...",
  str_n28_h12_name_desc = "Embora você não tenha certeza absoluta, o inimigo no centro do campo de batalha pode abrigar intenções ocultas...",
  str_n28_main_btn_unlock_time = "Desbloqueado após {1}{2}{3}",
